package com.glassbox.uml.trace; import com.glassbox.uml.event.EventBus; import java.lang.reflect.*; import java.util.Arrays;
/** Dynamic proxy decorator for interface-based tracing. */
public class TracingProxy implements InvocationHandler{private final Object target;private TracingProxy(Object t){target=t;}@SuppressWarnings("unchecked")public static <T>T create(Class<T> iface,T target){return (T)Proxy.newProxyInstance(iface.getClassLoader(),new Class<?>[]{iface},new TracingProxy(target));}public Object invoke(Object proxy,Method method,Object[] args)throws Throwable{if(!TraceConfig.TRACING_ENABLED)return invokeTarget(method,args);int depth=TraceConfig.getAndIncrementDepth();try{EventBus.getInstance().publish(new CallEvent("runtime",target.getClass().getSimpleName(),method.getName(),Arrays.toString(args==null?new Object[0]:args),depth));return invokeTarget(method,args);}finally{TraceConfig.decrementDepth();}}private Object invokeTarget(Method m,Object[] a)throws Throwable{try{return m.invoke(target,a);}catch(InvocationTargetException e){throw e.getCause();}}}
